{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    n = len(nodes)
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    edges = []
    for u, v, d in dists:
        w = max(core[u], core[v], d)
        if u > v:
            u, v = v, u
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = list(range(n))
    rank = [0]*n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    count = 0
    for w, u, v in edges:
        iu = node_to_idx[u]
        iv = node_to_idx[v]
        if union(iu, iv):
            mst_edges.append([u, v, w])
            total += w
            count += 1
            if count == n-1:
                break
    if count != n-1:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst_edges, 'total_weight': total}"
}
